int format_log_message(const char* raw_log, size_t log_len, char* formatted_buffer, size_t buffer_size) {
    // 检查输入参数的有效性
    if (raw_log == NULL || formatted_buffer == NULL || buffer_size == 0) {
        return -1; // 参数错误
    }

    // 如果原始日志为空，则直接返回
    if (raw_log == NULL || log_len == 0) {
        formatted_buffer[0] = '\0';
        return 0;
    }

    // 获取当前时间戳
    time_t current_time = time(NULL);
    struct tm *local_time = localtime(&current_time);

    // 格式化时间戳字符串
    char time_str[64];
    int time_len = strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", local_time);

    // 构建格式化的日志消息
    // 格式: [时间戳] [日志内容]\0
    const char* prefix = "[";
    const char* separator = "] [";
    const char* suffix = "]\0";

    size_t prefix_len = strlen(prefix);
    size_t separator_len = strlen(separator);
    size_t suffix_len = strlen(suffix);

    // 计算所需缓冲区大小
    size_t required_size = prefix_len + time_len + separator_len + log_len + suffix_len;

    // 检查缓冲区是否足够大
    if (required_size > buffer_size) {
        // 如果缓冲区不够大，尝试截断日志内容
        size_t available_space = buffer_size - prefix_len - time_len - separator_len - suffix_len;
        if (available_space <= 0) {
            return -2; // 缓冲区太小，连基本格式都放不下
        }

        // 截断原始日志以适应缓冲区
        log_len = (available_space > 0) ? available_space - 1 : 0; // 保留一个位置给终止符
    }

    // 构建格式化的日志消息
    size_t offset = 0;

    // 添加前缀 "["
    if (offset + prefix_len < buffer_size) {
        memcpy(formatted_buffer + offset, prefix, prefix_len);
        offset += prefix_len;
    } else {
        return -2; // 缓冲区不足
    }

    // 添加时间戳
    if (offset + time_len < buffer_size) {
        memcpy(formatted_buffer + offset, time_str, time_len);
        offset += time_len;
    } else {
        return -2; // 缓冲区不足
    }

    // 添加分隔符 "] ["
    if (offset + separator_len < buffer_size) {
        memcpy(formatted_buffer + offset, separator, separator_len);
        offset += separator_len;
    } else {
        return -2; // 缓冲区不足
    }

    // 添加原始日志内容（可能被截断）
    if (offset + log_len < buffer_size) {
        memcpy(formatted_buffer + offset, raw_log, log_len);
        offset += log_len;
    } else {
        return -2; // 缓冲区不足
    }

    // 添加后缀 "]"
    if (offset + suffix_len <= buffer_size) {
        memcpy(formatted_buffer + offset, suffix, suffix_len);
        offset += suffix_len - 1; // 不包括字符串终止符，因为它已经在suffix中了
    } else {
        // 如果空间不够，至少确保字符串终止
        if (offset < buffer_size) {
            formatted_buffer[offset] = '\0';
        } else {
            formatted_buffer[buffer_size - 1] = '\0';
        }
        return -2; // 缓冲区不足
    }

    // 确保字符串正确终止
    if (offset < buffer_size) {
        formatted_buffer[offset] = '\0';
    }

    return offset; // 返回实际写入的字符数（不包括终止符）
}
